package __PACKAGE__;

import com.mojang.serialization.Codec;
import net.minecraft.core.particles.ParticleType;

/**
 * The particle type of the Sparkle systems (Minecraft 1.20 to 1.20.4): it carries a {@link SparkleOptions} and is
 * sent to the players up to 512 blocks away.
 * Generated by the Sparkle plugin: do not edit, it is written again when the runtime is updated.
 */
public final class SparkleParticleType extends ParticleType<SparkleOptions> {
    @SuppressWarnings("deprecation")
    public SparkleParticleType() {
        super(true, SparkleOptions.DESERIALIZER);
    }

    @Override
    public Codec<SparkleOptions> codec() {
        return SparkleOptions.CODEC;
    }
}
